input.content:
/* ============================================================
   TOUCHLINE — football manager
   ============================================================ */
:root {
  --bg: #070b0e;
  --bg-2: #0b1115;
  --panel: #0f171c;
  --panel-2: #131e24;
  --panel-3: #18252d;
  --line: rgba(255, 255, 255, 0.09);
  --line-soft: rgba(255, 255, 255, 0.05);
  --text: #f2f6f4;
  --muted: #91a2a7;
  --muted-2: #66777c;
  --green: #38e07b;
  --green-2: #b8f23c;
  --green-dim: rgba(56, 224, 123, 0.14);
  --gold: #f4c95d;
  --blue: #65a9ff;
  --red: #ff6b70;
  --orange: #ffa45c;
  --purple: #b59cff;
  --radius: 18px;
  --radius-sm: 12px;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.36);
  --font: "Inter", "SF Pro Display", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-top: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(1200px 700px at 78% -10%, rgba(56, 224, 123, 0.09), transparent 60%),
    radial-gradient(900px 600px at 0% 100%, rgba(101, 169, 255, 0.06), transparent 60%),
    var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
body.match-open { overflow: hidden; }
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--green); text-decoration: none; }
h1, h2, h3, h4, p { margin: 0; }
h1, h2, h3, h4 { font-weight: 800; letter-spacing: -0.02em; }
::selection { background: var(--green); color: #041108; }

/* Scrollbars */
* { scrollbar-width: thin; scrollbar-color: #26343b transparent; }
*::-webkit-scrollbar { width: 8px; height: 8px; }
*::-webkit-scrollbar-thumb { background: #26343b; border-radius: 8px; }
*::-webkit-scrollbar-track { background: transparent; }

/* ============================================================
   Boot / landing
   ============================================================ */
.boot-screen {
  min-height: 100vh; display: grid; place-content: center; gap: 16px;
  text-align: center; background: radial-gradient(circle at 50% 40%, #102219 0, #070b0e 55%);
}
.boot-logo { font-size: clamp(34px, 7vw, 74px); font-weight: 900; letter-spacing: 0.18em; }
.boot-sub { color: var(--muted); letter-spacing: 0.08em; text-transform: uppercase; font-size: 11px; }
.boot-bar { width: min(280px, 68vw); height: 4px; background: #18252d; border-radius: 99px; overflow: hidden; margin: 14px auto 0; }
.boot-bar span { display: block; width: 45%; height: 100%; background: linear-gradient(90deg, var(--green), var(--green-2)); border-radius: 99px; animation: boot 1.1s ease-in-out infinite alternate; }
@keyframes boot { from { transform: translateX(-30%); } to { transform: translateX(150%); } }

.landing {
  min-height: 100vh;
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  gap: 0;
}
.landing-hero {
  position: relative; overflow: hidden;
  padding: clamp(28px, 6vw, 80px) clamp(24px, 5vw, 72px);
  display: flex; flex-direction: column; justify-content: space-between;
  background:
    linear-gradient(160deg, rgba(56, 224, 123, 0.08), transparent 40%),
    linear-gradient(0deg, #081014, #0a1216);
  border-right: 1px solid var(--line);
}
.landing-hero::before {
  content: ""; position: absolute; inset: -20% -20% auto auto; width: 70%; aspect-ratio: 1;
  background: radial-gradient(circle, rgba(56, 224, 123, 0.16), transparent 65%);
  pointer-events: none;
}
.landing-hero::after {
  content: ""; position: absolute; inset: auto auto -35% -20%; width: 70%; aspect-ratio: 1;
  background: radial-gradient(circle, rgba(101, 169, 255, 0.12), transparent 65%);
  pointer-events: none;
}
.hero-brand { display: flex; align-items: center; gap: 12px; font-weight: 900; letter-spacing: 0.16em; font-size: 15px; position: relative; }
.brand-mark {
  width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center;
  background: linear-gradient(135deg, var(--green), var(--green-2)); color: #041108;
  box-shadow: 0 8px 24px rgba(56, 224, 123, 0.25); flex: 0 0 auto;
}
.brand-mark svg { width: 22px; height: 22px; }
.hero-copy { position: relative; margin: clamp(30px, 7vh, 80px) 0; max-width: 620px; }
.eyebrow { display: inline-flex; align-items: center; gap: 8px; color: var(--green); font-size: 11px; font-weight: 800; letter-spacing: 0.16em; text-transform: uppercase; }
.hero-title { font-size: clamp(48px, 8vw, 106px); line-height: 0.9; letter-spacing: -0.055em; margin: 18px 0 24px; }
.hero-title .accent { color: var(--green); }
.hero-lead { color: var(--muted); font-size: clamp(15px, 1.6vw, 18px); max-width: 520px; }
.hero-features { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 34px; max-width: 560px; }
.feature {
  border: 1px solid var(--line); background: rgba(255, 255, 255, 0.025); border-radius: 14px;
  padding: 13px 14px; display: flex; gap: 12px; align-items: flex-start;
}
.feature-icon { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; background: var(--green-dim); color: var(--green); flex: 0 0 auto; }
.feature b { display: block; font-size: 13px; }
.feature span { color: var(--muted); font-size: 12px; line-height: 1.35; display: block; }
.hero-footer { position: relative; color: var(--muted-2); font-size: 11px; letter-spacing: 0.04em; }
.hero-footer b { color: var(--muted); }

.landing-panel {
  padding: clamp(22px, 4vw, 52px);
  display: flex; flex-direction: column; justify-content: center; gap: 20px;
  background: linear-gradient(180deg, rgba(255,255,255,0.015), transparent 30%);
  overflow: auto;
}
.panel-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.panel-title { font-size: clamp(24px, 3vw, 34px); }
.panel-sub { color: var(--muted); font-size: 13px; margin-top: 5px; }
.onb-name-wrap { display: grid; gap: 8px; }
.onb-label { font-size: 11px; font-weight: 800; letter-spacing: 0.13em; text-transform: uppercase; color: var(--muted); }
.input, .select {
  width: 100%; background: #0b1317; border: 1px solid var(--line); border-radius: 12px;
  padding: 12px 14px; color: var(--text); outline: none; transition: border-color .18s, box-shadow .18s;
  min-height: 46px;
}
.input:focus, .select:focus { border-color: rgba(56, 224, 123, 0.6); box-shadow: 0 0 0 3px rgba(56, 224, 123, 0.1); }
.input::placeholder { color: #5d6e73; }
.select { appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--muted) 50%), linear-gradient(135deg, var(--muted) 50%, transparent 50%); background-position: calc(100% - 18px) 50%, calc(100% - 13px) 50%; background-size: 5px 5px, 5px 5px; background-repeat: no-repeat; padding-right: 36px; }
.league-tabs { display: flex; gap: 7px; overflow-x: auto; padding-bottom: 2px; }
.league-tab {
  border: 1px solid var(--line); background: rgba(255,255,255,0.025); color: var(--muted);
  padding: 9px 13px; border-radius: 999px; font-size: 12px; font-weight: 700; white-space: nowrap;
  transition: .18s;
}
.league-tab:hover { color: var(--text); border-color: rgba(255,255,255,0.2); }
.league-tab.active { background: var(--green-dim); border-color: rgba(56,224,123,0.45); color: var(--green); }
.club-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; max-height: 330px; overflow: auto; padding-right: 4px; }
.club-card {
  display: flex; align-items: center; gap: 10px; text-align: left;
  background: rgba(255,255,255,0.02); border: 1px solid var(--line-soft);
  border-radius: 12px; padding: 9px 10px; transition: .18s; color: var(--text);
}
.club-card:hover { background: rgba(255,255,255,0.045); border-color: rgba(255,255,255,0.16); transform: translateY(-1px); }
.club-card.selected { border-color: rgba(56,224,123,0.65); background: var(--green-dim); box-shadow: inset 0 0 0 1px rgba(56,224,123,0.15); }
.club-card .club-name { font-size: 12px; font-weight: 700; line-height: 1.2; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.club-card .club-meta { font-size: 10px; color: var(--muted); margin-top: 2px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.club-card .club-text { min-width: 0; flex: 1; }
.club-detail {
  display: flex; align-items: center; gap: 14px; border: 1px solid var(--line);
  background: linear-gradient(135deg, rgba(255,255,255,0.035), rgba(255,255,255,0.01));
  border-radius: 16px; padding: 14px;
}
.club-detail .detail-name { font-size: 17px; font-weight: 800; }
.club-detail .detail-meta { color: var(--muted); font-size: 12px; margin-top: 2px; }
.club-detail .detail-budget { margin-left: auto; text-align: right; }
.club-detail .detail-budget b { display: block; font-size: 18px; color: var(--green); }
.club-detail .detail-budget span { font-size: 10px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.1em; }
.start-row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.start-row .btn { flex: 1; min-width: 180px; }
.continue-card {
  border: 1px solid rgba(56,224,123,0.25); background: linear-gradient(135deg, rgba(56,224,123,0.1), rgba(255,255,255,0.02));
  border-radius: var(--radius); padding: 18px; display: flex; gap: 14px; align-items: center; flex-wrap: wrap;
}
.continue-card .saved-club { display: flex; gap: 12px; align-items: center; flex: 1; min-width: 200px; }
.continue-card .saved-meta { color: var(--muted); font-size: 12px; }
.continue-card .saved-meta b { color: var(--text); }

/* ============================================================
   Main shell
   ============================================================ */
.shell { display: grid; grid-template-columns: 252px minmax(0, 1fr); min-height: 100vh; }
.sidebar {
  position: sticky; top: 0; height: 100vh; display: flex; flex-direction: column;
  background: linear-gradient(180deg, #0b1216, #080d10);
  border-right: 1px solid var(--line); padding: 20px 14px calc(14px + var(--safe-bottom)); z-index: 30;
}
.brand { display: flex; align-items: center; gap: 10px; padding: 0 6px 18px; border-bottom: 1px solid var(--line-soft); }
.brand .brand-name { font-weight: 900; letter-spacing: 0.14em; font-size: 14px; }
.brand .brand-tag { font-size: 9px; letter-spacing: 0.17em; color: var(--muted); text-transform: uppercase; margin-top: 1px; }
.club-summary { margin: 14px 0 10px; padding: 12px; border-radius: 14px; background: rgba(255,255,255,0.025); border: 1px solid var(--line-soft); display: flex; gap: 11px; align-items: center; }
.club-summary .cs-text { min-width: 0; }
.club-summary .cs-name { font-weight: 800; font-size: 13px; line-height: 1.2; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.club-summary .cs-meta { color: var(--muted); font-size: 10px; margin-top: 2px; letter-spacing: 0.04em; }
.side-nav { display: flex; flex-direction: column; gap: 3px; overflow: auto; flex: 1; padding: 4px 0; }
.nav-item {
  display: flex; align-items: center; gap: 11px; padding: 10px 11px; border-radius: 11px;
  color: var(--muted); font-size: 13px; font-weight: 650; border: 1px solid transparent; background: none;
  transition: .16s; text-align: left; width: 100%;
}
.nav-item:hover { color: var(--text); background: rgba(255,255,255,0.035); }
.nav-item.active { color: var(--text); background: linear-gradient(90deg, rgba(56,224,123,0.15), rgba(56,224,123,0.04)); border-color: rgba(56,224,123,0.15); }
.nav-item.active .nav-icon { color: var(--green); }
.nav-icon { width: 21px; height: 21px; display: grid; place-items: center; color: var(--muted-2); flex: 0 0 auto; }
.nav-icon svg { width: 19px; height: 19px; }
.nav-label { flex: 1; }
.nav-badge { font-size: 9px; font-weight: 800; padding: 2px 6px; border-radius: 99px; background: rgba(255,255,255,0.07); color: var(--muted); }
.side-footer { border-top: 1px solid var(--line-soft); padding-top: 12px; display: grid; gap: 7px; }
.side-note { font-size: 10px; color: var(--muted-2); padding: 0 4px; display: flex; justify-content: space-between; gap: 8px; }
.side-note .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); display: inline-block; margin-right: 5px; }

.main { min-width: 0; display: flex; flex-direction: column; }
.topbar {
  position: sticky; top: 0; z-index: 20;
  display: flex; align-items: center; gap: 16px; flex-wrap: wrap;
  padding: 15px clamp(16px, 3vw, 34px);
  background: rgba(7, 11, 14, 0.82); backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--line);
}
.topbar-title { font-size: 17px; font-weight: 800; letter-spacing: -0.01em; }
.topbar-sub { font-size: 11px; color: var(--muted); margin-top: 1px; }
.topbar-spacer { flex: 1; }
.topbar-meta { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.budget-chip {
  display: flex; flex-direction: column; gap: 1px; padding: 6px 10px; border-radius: 10px;
  background: rgba(255,255,255,0.035); border: 1px solid var(--line-soft); min-width: 90px;
}
.budget-chip span { font-size: 9px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.1em; }
.budget-chip b { font-size: 13px; color: var(--green); font-variant-numeric: tabular-nums; }
.budget-chip.wage b { color: var(--gold); }
.user-pill {
  display: flex; align-items: center; gap: 8px; border: 1px solid var(--line); background: rgba(255,255,255,0.03);
  border-radius: 999px; padding: 4px 10px 4px 4px;
}
.user-pill .pavatar { --size: 29px; }
.user-pill .up-name { font-size: 11px; font-weight: 700; line-height: 1.15; }
.user-pill .up-role { font-size: 9px; color: var(--muted); }

.view { padding: clamp(16px, 3vw, 34px); padding-bottom: 90px; max-width: 1560px; width: 100%; margin: 0 auto; animation: fade-up .25s ease both; }
@keyframes fade-up { from { opacity: 0; transform: translateY(7px); } to { opacity: 1; transform: none; } }

/* Mobile nav */
.mobile-nav { display: none; }

/* ============================================================
   Shared UI
   ============================================================ */
.page-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 18px; flex-wrap: wrap; margin-bottom: 20px; }
.page-title { font-size: clamp(24px, 3.2vw, 38px); line-height: 1.05; }
.page-sub { color: var(--muted); font-size: 13px; margin-top: 6px; max-width: 760px; }
.page-actions { display: flex; gap: 8px; flex-wrap: wrap; }

.grid { display: grid; gap: 14px; }
.grid.two { grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr); }
.grid.two-even { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid.three { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid.four { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.stack { display: grid; gap: 14px; }
.row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }

.card {
  background: linear-gradient(160deg, rgba(255,255,255,0.035), rgba(255,255,255,0.012));
  border: 1px solid var(--line); border-radius: var(--radius); padding: 18px;
  box-shadow: 0 1px 0 rgba(255,255,255,0.03) inset;
}
.card.pad-sm { padding: 14px; }
.card.flush { padding: 0; overflow: hidden; }
.card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
.card-title { font-size: 14px; font-weight: 800; letter-spacing: -0.01em; }
.card-sub { font-size: 11px; color: var(--muted); margin-top: 3px; }
.card-head .btn { flex: 0 0 auto; }

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  border: 1px solid var(--line); background: rgba(255,255,255,0.045); color: var(--text);
  border-radius: 11px; padding: 10px 14px; font-size: 12px; font-weight: 750; line-height: 1.1;
  transition: .16s; min-height: 40px; white-space: nowrap;
}
.btn:hover { background: rgba(255,255,255,0.09); border-color: rgba(255,255,255,0.2); transform: translateY(-1px); }
.btn:active { transform: none; }
.btn-primary { background: linear-gradient(135deg, var(--green), var(--green-2)); color: #041108; border-color: transparent; box-shadow: 0 8px 22px rgba(56,224,123,0.18); }
.btn-primary:hover { filter: brightness(1.06); background: linear-gradient(135deg, var(--green), var(--green-2)); }
.btn-ghost { background: transparent; }
.btn-danger { color: var(--red); border-color: rgba(255,107,112,0.28); background: rgba(255,107,112,0.08); }
.btn-danger:hover { background: rgba(255,107,112,0.15); }
.btn-gold { color: #2a1b00; background: linear-gradient(135deg, var(--gold), #ffe6a2); border-color: transparent; }
.btn-sm { padding: 6px 9px; font-size: 11px; min-height: 32px; border-radius: 8px; }
.btn-block { width: 100%; }
.btn:disabled { opacity: 0.42; cursor: not-allowed; transform: none; filter: none; }
.icon-btn { width: 36px; height: 36px; padding: 0; border-radius: 10px; display: grid; place-items: center; border: 1px solid var(--line); background: rgba(255,255,255,0.04); color: var(--muted); }
.icon-btn:hover { color: var(--text); background: rgba(255,255,255,0.09); }

.chip {
  display: inline-flex; align-items: center; gap: 5px; border-radius: 999px; padding: 4px 9px;
  background: rgba(255,255,255,0.05); border: 1px solid var(--line-soft);
  font-size: 10px; font-weight: 750; color: var(--muted); white-space: nowrap;
}
.chip.green { background: var(--green-dim); color: var(--green); border-color: rgba(56,224,123,0.25); }
.chip.gold { background: rgba(244,201,93,0.11); color: var(--gold); border-color: rgba(244,201,93,0.22); }
.chip.red { background: rgba(255,107,112,0.1); color: var(--red); border-color: rgba(255,107,112,0.22); }
.chip.blue { background: rgba(101,169,255,0.1); color: var(--blue); border-color: rgba(101,169,255,0.22); }
.chip.purple { background: rgba(181,156,255,0.1); color: var(--purple); border-color: rgba(181,156,255,0.22); }

.tag { display: inline-flex; align-items: center; border-radius: 6px; padding: 2px 6px; font-size: 9px; font-weight: 850; letter-spacing: 0.04em; text-transform: uppercase; background: rgba(255,255,255,0.07); color: var(--muted); }
.tag.green { background: var(--green-dim); color: var(--green); }
.tag.red { background: rgba(255,107,112,0.12); color: var(--red); }
.tag.gold { background: rgba(244,201,93,0.12); color: var(--gold); }
.tag.blue { background: rgba(101,169,255,0.12); color: var(--blue); }

.muted { color: var(--muted); }
.tiny { font-size: 10px; }
.small { font-size: 12px; }
.bold { font-weight: 800; }
.green-text { color: var(--green); }
.gold-text { color: var(--gold); }
.red-text { color: var(--red); }
.blue-text { color: var(--blue); }
.mono { font-variant-numeric: tabular-nums; }

/* Club crest */
.crest { --size: 44px; width: var(--size); height: var(--size); display: inline-grid; place-items: center; flex: 0 0 auto; position: relative; }
.crest-shield {
  width: 100%; height: 100%; position: relative; display: grid; place-items: center;
  clip-path: polygon(50% 0, 93% 12%, 88% 68%, 50% 100%, 12% 68%, 7% 12%);
  background: linear-gradient(145deg, var(--c1) 0 52%, var(--c2) 52% 100%);
  box-shadow: 0 5px 14px rgba(0,0,0,0.35);
  overflow: hidden;
}
.crest-shield::before {
  content: ""; position: absolute; inset: 3px; border: 1px solid rgba(255,255,255,0.32);
  clip-path: polygon(50% 0, 93% 12%, 88% 68%, 50% 100%, 12% 68%, 7% 12%);
  opacity: .7;
}
.crest-stripes { position: absolute; inset: 0; background: repeating-linear-gradient(120deg, transparent 0 7px, rgba(255,255,255,0.13) 7px 10px); opacity: .6; }
.crest-code {
  position: relative; z-index: 2; font-size: calc(var(--size) * 0.26); font-weight: 950;
  letter-spacing: -0.04em; color: var(--ink, #fff); text-shadow: 0 1px 2px rgba(0,0,0,0.35);
  padding-top: 1px;
}
.crest-star { position: absolute; top: -4px; right: -3px; z-index: 3; color: var(--gold); font-size: calc(var(--size) * 0.28); filter: drop-shadow(0 1px 2px #000); }
.crest.lg { --size: 66px; }
.crest.xl { --size: 96px; }

/* Player avatar */
.pavatar {
  --size: 36px; width: var(--size); height: var(--size); border-radius: 50%; display: inline-grid; place-items: center;
  font-size: calc(var(--size) * 0.29); font-weight: 900; color: #06110a; flex: 0 0 auto;
  background: linear-gradient(135deg, #c8d6d0, #93aaa2); border: 1px solid rgba(255,255,255,0.3);
  letter-spacing: -0.03em;
}
.pavatar.pos-gk { background: linear-gradient(135deg, #ffd166, #f0a511); }
.pavatar.pos-def { background: linear-gradient(135deg, #7ec8ff, #2f8ad6); }
.pavatar.pos-mid { background: linear-gradient(135deg, #7ef0aa, #2fc96b); }
.pavatar.pos-att { background: linear-gradient(135deg, #ff9c8a, #e84a3f); }

.nation { font-size: 12px; line-height: 1; }

/* Stat cards */
.stats-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; margin-bottom: 14px; }
.stat-card { background: rgba(255,255,255,0.028); border: 1px solid var(--line); border-radius: 14px; padding: 13px 14px; }
.stat-label { font-size: 10px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.11em; font-weight: 750; }
.stat-value { font-size: 24px; font-weight: 850; margin-top: 5px; letter-spacing: -0.04em; line-height: 1; }
.stat-value small { font-size: 11px; color: var(--muted); font-weight: 650; letter-spacing: 0; }
.stat-note { font-size: 10px; color: var(--muted); margin-top: 5px; }

/* Meters */
.meter { height: 7px; background: rgba(255,255,255,0.07); border-radius: 999px; overflow: hidden; }
.meter > span { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, var(--green), var(--green-2)); transition: width .4s ease; }
.meter.gold > span { background: linear-gradient(90deg, var(--gold), #ffe6a2); }
.meter.red > span { background: linear-gradient(90deg, var(--red), #ff9a9d); }
.meter.blue > span { background: linear-gradient(90deg, var(--blue), #9bc9ff); }

/* ============================================================
   Dashboard
   ============================================================ */
.dash-hero {
  position: relative; overflow: hidden; border-radius: 22px; border: 1px solid var(--line);
  background:
    radial-gradient(700px 200px at 85% -20%, rgba(56,224,123,0.17), transparent 70%),
    linear-gradient(135deg, #101d22, #0b1216 70%);
  padding: clamp(18px, 3vw, 28px); margin-bottom: 14px;
}
.dash-hero::after {
  content: ""; position: absolute; inset: auto -10% -80% 40%; height: 260px;
  background: radial-gradient(ellipse, rgba(101,169,255,0.13), transparent 65%); pointer-events: none;
}
.hero-top { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; align-items: flex-start; position: relative; z-index: 2; }
.hero-club { display: flex; gap: 14px; align-items: center; min-width: 0; }
.hero-club .hc-name { font-size: clamp(22px, 3vw, 34px); font-weight: 900; letter-spacing: -0.045em; line-height: 1.05; }
.hero-club .hc-meta { color: var(--muted); font-size: 12px; margin-top: 4px; display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.hero-next { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; justify-content: flex-end; }
.next-card-mini { background: rgba(0,0,0,0.22); border: 1px solid var(--line); border-radius: 14px; padding: 10px 12px; min-width: 250px; }
.next-card-mini .ncm-label { font-size: 9px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); margin-bottom: 7px; }
.ncm-teams { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 800; }
.ncm-teams .vs { color: var(--muted-2); font-size: 10px; font-weight: 700; }
.ncm-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 7px; font-size: 10px; color: var(--muted); }

.next-match {
  display: grid; grid-template-columns: 1fr auto 1fr; gap: 12px; align-items: center;
  padding: 16px; border-radius: 16px; background: rgba(0,0,0,0.2); border: 1px solid var(--line);
}
.next-team { display: flex; flex-direction: column; align-items: center; gap: 8px; text-align: center; min-width: 0; }
.next-team .nt-name { font-size: 12px; font-weight: 800; line-height: 1.2; }
.next-team .nt-meta { font-size: 9px; color: var(--muted); }
.next-vs { display: grid; gap: 4px; place-items: center; min-width: 64px; }
.next-vs .vs-label { font-size: 9px; color: var(--muted); letter-spacing: 0.12em; text-transform: uppercase; }
.next-vs .vs-time { font-size: 18px; font-weight: 900; }
.next-vs .vs-md { font-size: 9px; color: var(--green); font-weight: 800; }
.match-actions { display: flex; gap: 8px; margin-top: 12px; flex-wrap: wrap; }
.match-actions .btn { flex: 1; min-width: 120px; }

.form-strip { display: flex; gap: 5px; flex-wrap: wrap; }
.form-chip {
  width: 24px; height: 24px; border-radius: 7px; display: grid; place-items: center;
  font-size: 10px; font-weight: 900; background: rgba(255,255,255,0.07); color: var(--muted);
}
.form-chip.W { background: rgba(56,224,123,0.18); color: var(--green); }
.form-chip.D { background: rgba(244,201,93,0.15); color: var(--gold); }
.form-chip.L { background: rgba(255,107,112,0.15); color: var(--red); }

.news-list { display: grid; gap: 2px; max-height: 380px; overflow: auto; }
.news-item { display: flex; gap: 11px; padding: 10px 2px; border-bottom: 1px solid var(--line-soft); }
.news-item:last-child { border-bottom: 0; }
.news-icon { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; flex: 0 0 auto; background: rgba(255,255,255,0.06); color: var(--muted); font-size: 12px; }
.news-icon.win { background: var(--green-dim); color: var(--green); }
.news-icon.loss { background: rgba(255,107,112,0.12); color: var(--red); }
.news-icon.transfer { background: rgba(101,169,255,0.12); color: var(--blue); }
.news-icon.board { background: rgba(244,201,93,0.12); color: var(--gold); }
.news-icon.youth { background: rgba(181,156,255,0.12); color: var(--purple); }
.news-text { font-size: 12px; line-height: 1.45; color: #d7e0dd; }
.news-meta { font-size: 9px; color: var(--muted-2); margin-top: 3px; letter-spacing: 0.03em; }

.quick-table { width: 100%; border-collapse: collapse; }
.quick-table th { font-size: 9px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); text-align: right; padding: 5px 4px; font-weight: 800; }
.quick-table th:nth-child(2) { text-align: left; }
.quick-table td { padding: 6px 4px; font-size: 11px; border-top: 1px solid var(--line-soft); text-align: right; font-variant-numeric: tabular-nums; }
.quick-table td:nth-child(2) { text-align: left; }
.quick-table tr.me td { background: rgba(56,224,123,0.08); }
.quick-table .club-inline { display: flex; align-items: center; gap: 7px; min-width: 0; }
.quick-table .club-inline .crest { --size: 20px; }
.quick-table .club-inline span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.confidence-box { display: grid; gap: 9px; }
.confidence-top { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.confidence-top b { font-size: 16px; }
.confidence-top span { font-size: 11px; color: var(--muted); }

.mini-stat-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 8px 0; border-bottom: 1px solid var(--line-soft); font-size: 12px; }
.mini-stat-row:last-child { border-bottom: 0; }
.mini-stat-row b { font-variant-numeric: tabular-nums; }

.top-scorer-card { display: flex; align-items: center; gap: 11px; padding: 9px 0; border-bottom: 1px solid var(--line-soft); }
.top-scorer-card:last-child { border-bottom: 0; }
.ts-rank { font-size: 11px; color: var(--muted-2); width: 16px; font-weight: 800; }
.ts-info { flex: 1; min-width: 0; }
.ts-name { font-size: 12px; font-weight: 750; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ts-club { font-size: 10px; color: var(--muted); }
.ts-goals { font-size: 17px; font-weight: 900; color: var(--green); }

/* ============================================================
   Tables
   ============================================================ */
.table-wrap { overflow: auto; border-radius: 12px; border: 1px solid var(--line-soft); }
.data-table { width: 100%; border-collapse: collapse; min-width: 760px; }
.data-table thead th {
  position: sticky; top: 0; z-index: 2; background: #101b20; color: var(--muted);
  font-size: 9px; letter-spacing: 0.1em; text-transform: uppercase; font-weight: 850;
  padding: 10px 10px; text-align: left; border-bottom: 1px solid var(--line); white-space: nowrap;
}
.data-table thead th.num, .data-table td.num { text-align: right; font-variant-numeric: tabular-nums; }
.data-table thead th.center, .data-table td.center { text-align: center; }
.data-table tbody td { padding: 9px 10px; border-bottom: 1px solid var(--line-soft); font-size: 12px; vertical-align: middle; }
.data-table tbody tr:last-child td { border-bottom: 0; }
.data-table tbody tr { transition: background .15s; }
.data-table tbody tr:hover { background: rgba(255,255,255,0.035); }
.data-table tbody tr.me { background: rgba(56,224,123,0.065); }
.data-table tbody tr.me:hover { background: rgba(56,224,123,0.1); }
.data-table th.sortable { cursor: pointer; user-select: none; }
.data-table th.sortable:hover { color: var(--text); }
.data-table th .sort-arrow { color: var(--green); margin-left: 3px; }
.table-club { display: flex; align-items: center; gap: 9px; min-width: 0; }
.table-club .crest { --size: 25px; }
.table-club .tc-name { font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.table-club .tc-sub { font-size: 9px; color: var(--muted); }
.player-cell { display: flex; align-items: center; gap: 9px; min-width: 0; }
.player-cell .pavatar { --size: 29px; }
.player-cell .pc-name { font-weight: 750; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.player-cell .pc-meta { font-size: 9px; color: var(--muted); margin-top: 1px; display: flex; gap: 5px; align-items: center; }
.ovr { display: inline-grid; place-items: center; min-width: 30px; height: 25px; border-radius: 7px; font-weight: 900; font-size: 12px; background: rgba(255,255,255,0.06); font-variant-numeric: tabular-nums; }
.ovr.elite { background: rgba(56,224,123,0.18); color: var(--green); }
.ovr.great { background: rgba(184,242,60,0.16); color: var(--green-2); }
.ovr.good { background: rgba(101,169,255,0.14); color: var(--blue); }
.ovr.ok { background: rgba(244,201,93,0.13); color: var(--gold); }
.ovr.low { background: rgba(255,255,255,0.06); color: var(--muted); }
.pot { font-size: 11px; font-weight: 800; color: var(--muted); }
.pot.up { color: var(--green); }
.pot.max { color: var(--gold); }
.pos-tag { display: inline-grid; place-items: center; min-width: 30px; padding: 3px 5px; border-radius: 6px; font-size: 9px; font-weight: 850; background: rgba(255,255,255,0.07); color: var(--muted); }
.pos-tag.GK { background: rgba(244,201,93,0.13); color: var(--gold); }
.pos-tag.DEF { background: rgba(101,169,255,0.13); color: var(--blue); }
.pos-tag.MID { background: rgba(56,224,123,0.13); color: var(--green); }
.pos-tag.ATT { background: rgba(255,107,112,0.13); color: var(--red); }

.table-toolbar { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 12px; }
.table-toolbar .spacer { flex: 1; }
.table-toolbar .select, .table-toolbar .input { width: auto; min-height: 36px; padding: 7px 12px; font-size: 12px; }
.table-toolbar .select { padding-right: 32px; }

/* ============================================================
   Transfers / filters
   ============================================================ */
.filters { display: grid; grid-template-columns: minmax(160px, 1.6fr) repeat(4, minmax(100px, 1fr)); gap: 8px; margin-bottom: 12px; }
.filter { display: grid; gap: 4px; }
.filter label { font-size: 9px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); font-weight: 800; padding-left: 2px; }
.filter .input, .filter .select { min-height: 38px; padding: 8px 10px; font-size: 12px; border-radius: 9px; }
.market-head { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; margin-bottom: 8px; }
.market-count { font-size: 11px; color: var(--muted); }
.market-count b { color: var(--text); }
.market-actions { display: flex; gap: 6px; align-items: center; }

.empty-state { padding: 36px 18px; text-align: center; color: var(--muted); }
.empty-state .es-icon { width: 48px; height: 48px; border-radius: 14px; margin: 0 auto 10px; display: grid; place-items: center; background: rgba(255,255,255,0.05); color: var(--muted); }
.empty-state b { display: block; color: var(--text); font-size: 14px; margin-bottom: 3px; }
.empty-state span { font-size: 12px; }

/* ============================================================
   Squad / lineup
   ============================================================ */
.squad-summary { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; margin-bottom: 12px; }
.squad-summary .mini { background: rgba(255,255,255,0.03); border: 1px solid var(--line-soft); border-radius: 12px; padding: 10px 12px; }
.squad-summary .mini span { font-size: 9px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.1em; font-weight: 800; }
.squad-summary .mini b { display: block; font-size: 18px; margin-top: 2px; letter-spacing: -0.03em; }

.lineup-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.lineup-slot { display: grid; gap: 4px; }
.lineup-slot label { font-size: 9px; color: var(--muted); font-weight: 800; text-transform: uppercase; letter-spacing: 0.08em; }
.lineup-slot .select { min-height: 38px; padding: 7px 30px 7px 9px; font-size: 11px; }
.formation-pitch { display: grid; grid-template-columns: repeat(5, 1fr); gap: 7px; margin-bottom: 14px; }
.formation-dot { aspect-ratio: 1; border-radius: 50%; border: 1px solid rgba(56,224,123,0.35); background: rgba(56,224,123,0.1); display: grid; place-items: center; font-size: 9px; font-weight: 800; color: var(--green); }
.formation-empty { border-color: var(--line); background: rgba(255,255,255,0.03); color: var(--muted); }

/* ============================================================
   Academy / staff
   ============================================================ */
.academy-banner {
  display: flex; align-items: center; gap: 16px; flex-wrap: wrap;
  background: radial-gradient(600px 160px at 10% 0, rgba(181,156,255,0.14), transparent 70%), linear-gradient(135deg, #141b2a, #0e151b);
  border: 1px solid rgba(181,156,255,0.18); border-radius: 20px; padding: 18px; margin-bottom: 14px;
}
.academy-banner .ab-icon { width: 54px; height: 54px; border-radius: 16px; display: grid; place-items: center; background: rgba(181,156,255,0.14); color: var(--purple); flex: 0 0 auto; }
.academy-banner .ab-title { font-size: 18px; font-weight: 850; }
.academy-banner .ab-sub { color: var(--muted); font-size: 12px; }
.academy-banner .ab-stars { font-size: 15px; color: var(--purple); letter-spacing: 2px; }
.academy-banner .ab-actions { margin-left: auto; display: flex; gap: 7px; flex-wrap: wrap; }

.coach-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.coach-card { background: rgba(255,255,255,0.03); border: 1px solid var(--line); border-radius: 14px; padding: 13px; display: grid; gap: 9px; }
.coach-card .cc-top { display: flex; align-items: flex-start; gap: 10px; }
.coach-card .cc-avatar { width: 38px; height: 38px; border-radius: 11px; display: grid; place-items: center; background: rgba(56,224,123,0.12); color: var(--green); font-weight: 900; font-size: 14px; }
.coach-card .cc-name { font-size: 13px; font-weight: 800; line-height: 1.2; }
.coach-card .cc-role { font-size: 10px; color: var(--muted); margin-top: 2px; }
.coach-card .cc-stars { color: var(--gold); font-size: 11px; letter-spacing: 1px; }
.coach-card .cc-effect { font-size: 10px; color: var(--muted); line-height: 1.35; }
.coach-card .cc-bottom { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding-top: 7px; border-top: 1px solid var(--line-soft); font-size: 10px; color: var(--muted); }
.coach-card .cc-wage { color: var(--gold); font-weight: 800; }
.coach-card.empty { border-style: dashed; background: transparent; }
.coach-card.empty .cc-avatar { background: rgba(255,255,255,0.05); color: var(--muted); }

.staff-tabs { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 12px; }
.staff-tab { border: 1px solid var(--line); background: rgba(255,255,255,0.03); border-radius: 999px; padding: 6px 11px; font-size: 11px; font-weight: 700; color: var(--muted); }
.staff-tab.active { background: var(--green-dim); border-color: rgba(56,224,123,0.35); color: var(--green); }

.youth-note { font-size: 11px; color: var(--muted); display: flex; gap: 7px; align-items: flex-start; padding: 10px 12px; background: rgba(181,156,255,0.06); border: 1px solid rgba(181,156,255,0.14); border-radius: 11px; margin-bottom: 12px; }

/* ============================================================
   Leagues / fixtures
   ============================================================ */
.league-tabs-lg { display: flex; gap: 7px; overflow-x: auto; margin-bottom: 14px; padding-bottom: 2px; }
.league-tab-lg {
  display: flex; align-items: center; gap: 8px; padding: 10px 13px; border-radius: 11px;
  border: 1px solid var(--line); background: rgba(255,255,255,0.025); color: var(--muted);
  font-size: 12px; font-weight: 750; white-space: nowrap;
}
.league-tab-lg.active { background: rgba(56,224,123,0.09); border-color: rgba(56,224,123,0.35); color: var(--text); }
.league-tab-lg .lt-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--lg-color, var(--green)); }
.league-table-wrap { overflow: auto; }
.league-table { width: 100%; border-collapse: collapse; min-width: 660px; }
.league-table th { font-size: 9px; text-transform: uppercase; letter-spacing: 0.09em; color: var(--muted); padding: 9px 8px; text-align: center; border-bottom: 1px solid var(--line); }
.league-table th.left { text-align: left; }
.league-table td { padding: 8px; border-bottom: 1px solid var(--line-soft); font-size: 12px; text-align: center; font-variant-numeric: tabular-nums; }
.league-table td.left { text-align: left; }
.league-table tr.me { background: rgba(56,224,123,0.075); }
.league-table tr.champion { background: rgba(244,201,93,0.07); }
.league-table tr.relegation { background: rgba(255,107,112,0.045); }
.league-table tr.qual { background: rgba(101,169,255,0.045); }
.league-table .pos-indicator { width: 3px; height: 20px; border-radius: 3px; display: inline-block; background: transparent; vertical-align: middle; margin-right: 5px; }
.league-table tr.champion .pos-indicator { background: var(--gold); }
.league-table tr.qual .pos-indicator { background: var(--blue); }
.league-table tr.relegation .pos-indicator { background: var(--red); }
.fixture-list { display: grid; gap: 7px; }
.fixture-row {
  display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 8px;
  padding: 9px 11px; border-radius: 10px; background: rgba(255,255,255,0.025); border: 1px solid var(--line-soft);
}
.fixture-row.user { border-color: rgba(56,224,123,0.25); background: rgba(56,224,123,0.06); }
.fixture-team { display: flex; align-items: center; gap: 7px; min-width: 0; font-size: 11px; font-weight: 700; }
.fixture-team.away { justify-content: flex-end; text-align: right; }
.fixture-team .crest { --size: 23px; }
.fixture-team span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fixture-score { min-width: 52px; text-align: center; font-weight: 900; font-size: 13px; font-variant-numeric: tabular-nums; }
.fixture-score .fs-time { display: block; font-size: 9px; color: var(--muted); font-weight: 700; }
.fixture-score .fs-time.user { color: var(--green); }
.round-nav { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; }
.round-nav .select { width: auto; min-height: 38px; padding: 7px 32px 7px 10px; font-size: 12px; }

/* ============================================================
   Finances
   ============================================================ */
.fin-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.fin-card { background: rgba(255,255,255,0.03); border: 1px solid var(--line); border-radius: 14px; padding: 14px; }
.fin-card .fc-label { font-size: 10px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.1em; font-weight: 800; }
.fin-card .fc-value { font-size: 24px; font-weight: 900; margin-top: 5px; letter-spacing: -0.04em; }
.fin-card .fc-note { font-size: 10px; color: var(--muted); margin-top: 4px; }
.fin-card.green .fc-value { color: var(--green); }
.fin-card.gold .fc-value { color: var(--gold); }
.fin-card.red .fc-value { color: var(--red); }
.fin-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 9px 0; border-bottom: 1px solid var(--line-soft); font-size: 12px; }
.fin-row:last-child { border-bottom: 0; }
.fin-row b { font-variant-numeric: tabular-nums; }
.fin-bar-row { display: grid; gap: 6px; margin: 8px 0; }
.fin-bar-row .fbr-top { display: flex; justify-content: space-between; gap: 8px; font-size: 11px; color: var(--muted); }
.fin-bar-row .fbr-top b { color: var(--text); }

/* ============================================================
   Modal
   ============================================================ */
#modal-root { position: relative; z-index: 100; }
.modal-backdrop {
  position: fixed; inset: 0; background: rgba(2, 6, 8, 0.72); backdrop-filter: blur(7px);
  display: grid; place-items: center; padding: 18px; z-index: 100; animation: fade .18s ease;
}
@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
.modal {
  width: min(720px, 100%); max-height: min(88vh, 920px); overflow: auto;
  background: linear-gradient(165deg, #121d23, #0c1317);
  border: 1px solid rgba(255,255,255,0.13); border-radius: 20px;
  box-shadow: 0 30px 100px rgba(0,0,0,0.65); animation: modal-in .2s ease both;
}
.modal.wide { width: min(980px, 100%); }
.modal.narrow { width: min(480px, 100%); }
@keyframes modal-in { from { opacity: 0; transform: translateY(10px) scale(.985); } to { opacity: 1; transform: none; } }
.modal-head { display: flex; align-items: flex-start; gap: 12px; padding: 18px 20px 13px; border-bottom: 1px solid var(--line-soft); position: sticky; top: 0; background: rgba(18,29,35,0.94); backdrop-filter: blur(10px); z-index: 3; }
.modal-head .mh-text { flex: 1; min-width: 0; }
.modal-title { font-size: 18px; font-weight: 850; letter-spacing: -0.02em; }
.modal-sub { font-size: 11px; color: var(--muted); margin-top: 3px; }
.close-btn { width: 34px; height: 34px; border-radius: 9px; border: 1px solid var(--line); background: rgba(255,255,255,0.04); color: var(--muted); display: grid; place-items: center; font-size: 18px; line-height: 1; }
.close-btn:hover { color: var(--text); background: rgba(255,255,255,0.09); }
.modal-body { padding: 18px 20px 20px; }
.modal-foot { display: flex; justify-content: flex-end; gap: 8px; flex-wrap: wrap; padding: 13px 20px 18px; border-top: 1px solid var(--line-soft); }

.player-hero { display: flex; gap: 14px; align-items: center; margin-bottom: 15px; flex-wrap: wrap; }
.player-hero .pavatar { --size: 64px; }
.player-hero .ph-name { font-size: 21px; font-weight: 900; letter-spacing: -0.03em; line-height: 1.1; }
.player-hero .ph-meta { display: flex; gap: 7px; flex-wrap: wrap; align-items: center; color: var(--muted); font-size: 11px; margin-top: 5px; }
.player-hero .ph-club { margin-left: auto; display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--muted); }
.player-hero .ph-club .crest { --size: 30px; }
.detail-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-bottom: 14px; }
.detail-box { background: rgba(255,255,255,0.028); border: 1px solid var(--line-soft); border-radius: 10px; padding: 9px 10px; }
.detail-box span { display: block; font-size: 9px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.09em; font-weight: 800; }
.detail-box b { display: block; font-size: 14px; margin-top: 2px; font-variant-numeric: tabular-nums; }
.attr-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px 18px; }
.attr { display: grid; gap: 4px; }
.attr-top { display: flex; justify-content: space-between; gap: 8px; font-size: 10px; color: var(--muted); font-weight: 700; }
.attr-top b { color: var(--text); font-variant-numeric: tabular-nums; }
.attr-bar { height: 5px; background: rgba(255,255,255,0.07); border-radius: 99px; overflow: hidden; }
.attr-bar span { display: block; height: 100%; border-radius: 99px; background: linear-gradient(90deg, var(--green), var(--green-2)); }
.attr-bar.blue span { background: linear-gradient(90deg, var(--blue), #a7d1ff); }
.attr-bar.red span { background: linear-gradient(90deg, var(--red), #ffb2b4); }
.attr-bar.gold span { background: linear-gradient(90deg, var(--gold), #ffe9ae); }
.form-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 9px; margin: 12px 0 4px; }
.form-row .field { display: grid; gap: 4px; }
.form-row label { font-size: 9px; text-transform: uppercase; letter-spacing: 0.1em; color: var(--muted); font-weight: 800; }
.form-row .input, .form-row .select { min-height: 40px; padding: 8px 10px; font-size: 13px; }
.offer-box { background: rgba(56,224,123,0.06); border: 1px solid rgba(56,224,123,0.18); border-radius: 11px; padding: 11px 12px; margin: 10px 0; display: grid; gap: 5px; font-size: 11px; color: var(--muted); }
.offer-box b { color: var(--text); }
.offer-box .big { color: var(--green); font-size: 19px; font-weight: 900; letter-spacing: -0.03em; }
.modal-note { font-size: 11px; color: var(--muted); line-height: 1.5; margin-top: 10px; }
.msg { border-radius: 10px; padding: 10px 12px; font-size: 12px; line-height: 1.45; margin: 10px 0; border: 1px solid var(--line); background: rgba(255,255,255,0.04); }
.msg.ok { background: rgba(56,224,123,0.08); border-color: rgba(56,224,123,0.25); color: var(--green); }
.msg.bad { background: rgba(255,107,112,0.08); border-color: rgba(255,107,112,0.25); color: var(--red); }
.msg.info { background: rgba(101,169,255,0.08); border-color: rgba(101,169,255,0.22); color: #cfe4ff; }

.offer-list { display: grid; gap: 8px; }
.offer-item { display: flex; align-items: center; gap: 10px; padding: 10px 11px; background: rgba(255,255,255,0.03); border: 1px solid var(--line-soft); border-radius: 11px; }
.offer-item .oi-text { flex: 1; min-width: 0; }
.offer-item .oi-name { font-size: 12px; font-weight: 750; }
.offer-item .oi-meta { font-size: 10px; color: var(--muted); }
.offer-item .oi-amount { font-size: 16px; font-weight: 900; color: var(--green); }

.season-summary-hero { text-align: center; padding: 10px 0 18px; }
.season-summary-hero .ssh-label { font-size: 10px; text-transform: uppercase; letter-spacing: 0.16em; color: var(--green); font-weight: 850; }
.season-summary-hero .ssh-title { font-size: clamp(28px, 6vw, 46px); font-weight: 950; letter-spacing: -0.05em; line-height: 1; margin-top: 8px; }
.season-summary-hero .ssh-sub { color: var(--muted); font-size: 12px; margin-top: 6px; }
.summary-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; margin: 14px 0; }
.summary-box { background: rgba(255,255,255,0.03); border: 1px solid var(--line-soft); border-radius: 10px; padding: 10px; text-align: center; }
.summary-box span { display: block; font-size: 9px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.09em; font-weight: 800; }
.summary-box b { display: block; font-size: 18px; font-weight: 900; margin-top: 2px; }

/* ============================================================
   Match overlay
   ============================================================ */
#match-root { position: relative; z-index: 120; }
.match-overlay {
  position: fixed; inset: 0; z-index: 120; overflow: auto;
  background:
    radial-gradient(900px 500px at 50% -10%, rgba(56,224,123,0.12), transparent 65%),
    linear-gradient(180deg, #07110c, #060a0c 60%);
  padding: 18px clamp(12px, 3vw, 30px) calc(20px + var(--safe-bottom));
  animation: fade .2s ease;
}
.match-header { max-width: 1180px; margin: 0 auto 12px; }
.match-comp { text-align: center; font-size: 10px; color: var(--muted); letter-spacing: 0.14em; text-transform: uppercase; font-weight: 800; }
.match-scoreline { display: grid; grid-template-columns: 1fr auto 1fr; gap: 10px; align-items: center; margin-top: 10px; }
.match-team { display: flex; align-items: center; gap: 12px; min-width: 0; }
.match-team.away { justify-content: flex-end; text-align: right; }
.match-team .mt-name { font-size: clamp(13px, 2.4vw, 20px); font-weight: 900; line-height: 1.1; letter-spacing: -0.02em; }
.match-team .mt-sub { font-size: 9px; color: var(--muted); margin-top: 2px; }
.match-score { display: flex; align-items: center; gap: 10px; font-size: clamp(34px, 7vw, 64px); font-weight: 950; letter-spacing: -0.06em; line-height: 1; font-variant-numeric: tabular-nums; }
.match-score .dash { color: var(--muted-2); font-size: 0.7em; }
.match-clock { text-align: center; font-size: 13px; font-weight: 900; color: var(--green); margin-top: 7px; letter-spacing: 0.05em; }
.match-grid { display: grid; grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.45fr) minmax(0, 0.85fr); gap: 12px; max-width: 1180px; margin: 0 auto; }
.match-feed-wrap, .match-pitch-wrap, .match-side { background: rgba(255,255,255,0.028); border: 1px solid var(--line); border-radius: 16px; padding: 13px; min-height: 0; }
.match-feed-wrap { display: flex; flex-direction: column; }
.match-feed-wrap h3, .match-side h3 { font-size: 11px; text-transform: uppercase; letter-spacing: 0.11em; color: var(--muted); margin-bottom: 9px; }
.match-feed { display: flex; flex-direction: column; gap: 6px; overflow: auto; max-height: 390px; padding-right: 4px; flex: 1; }
.feed-event { display: flex; gap: 8px; font-size: 11px; line-height: 1.4; padding: 6px 7px; border-radius: 8px; background: rgba(255,255,255,0.025); animation: feed-in .22s ease both; }
@keyframes feed-in { from { opacity: 0; transform: translateX(-5px); } to { opacity: 1; transform: none; } }
.feed-event .fe-min { min-width: 24px; color: var(--muted-2); font-weight: 800; font-variant-numeric: tabular-nums; }
.feed-event .fe-text { flex: 1; color: #ccd8d4; }
.feed-event.goal { background: rgba(56,224,123,0.12); border-left: 2px solid var(--green); }
.feed-event.goal .fe-text { color: #dfffea; font-weight: 700; }
.feed-event.yellow { background: rgba(244,201,93,0.08); }
.feed-event.red { background: rgba(255,107,112,0.1); }
.feed-event.half, .feed-event.full { background: rgba(255,255,255,0.05); color: var(--muted); }
.feed-event.chance .fe-text { color: var(--muted); }

.pitch {
  position: relative; aspect-ratio: 16 / 10; border-radius: 12px; overflow: hidden;
  background: repeating-linear-gradient(90deg, #16532e 0 8.33%, #124a29 8.33% 16.66%);
  border: 2px solid rgba(255,255,255,0.15); margin-bottom: 12px;
}
.pitch::before { content: ""; position: absolute; inset: 5%; border: 1px solid rgba(255,255,255,0.22); }
.pitch::after { content: ""; position: absolute; width: 26%; aspect-ratio: 1; border: 1px solid rgba(255,255,255,0.22); border-radius: 50%; left: 37%; top: 50%; transform: translateY(-50%); }
.pitch-halfway { position: absolute; left: 50%; top: 0; bottom: 0; width: 1px; background: rgba(255,255,255,0.22); }
.pitch-box { position: absolute; top: 50%; width: 15%; height: 48%; border: 1px solid rgba(255,255,255,0.22); transform: translateY(-50%); }
.pitch-box.left { left: 5%; border-left: 0; }
.pitch-box.right { right: 5%; border-right: 0; }
.pitch-goal { position: absolute; top: 50%; width: 2.5%; height: 18%; background: rgba(255,255,255,0.18); border: 1px solid rgba(255,255,255,0.3); transform: translateY(-50%); }
.pitch-goal.left { left: 2.2%; }
.pitch-goal.right { right: 2.2%; }
.match-ball {
  position: absolute; width: 12px; height: 12px; border-radius: 50%; background: #fff;
  box-shadow: 0 0 0 3px rgba(0,0,0,0.25), 0 4px 10px rgba(0,0,0,0.4); left: 50%; top: 50%;
  transform: translate(-50%, -50%); transition: left .5s ease, top .5s ease; z-index: 3;
}
.match-ball::after { content: ""; position: absolute; inset: 2px; border-radius: 50%; background: #0b1216; opacity: .25; }
.pitch-label { position: absolute; bottom: 6px; font-size: 8px; font-weight: 850; color: rgba(255,255,255,0.6); letter-spacing: 0.08em; }
.pitch-label.home { left: 8px; }
.pitch-label.away { right: 8px; }

.match-stats { display: grid; gap: 7px; }
.stat-line { display: grid; grid-template-columns: 32px 1fr 32px; gap: 8px; align-items: center; font-size: 10px; font-weight: 800; font-variant-numeric: tabular-nums; }
.stat-line .sl-mid { display: grid; gap: 3px; }
.stat-line .sl-label { text-align: center; font-size: 8px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }
.stat-track { height: 5px; background: rgba(255,255,255,0.09); border-radius: 99px; overflow: hidden; display: flex; }
.stat-track .home { height: 100%; background: var(--green); }
.stat-track .away { height: 100%; background: var(--red); margin-left: auto; }
.stat-line .num-right { text-align: right; }

.match-side .side-block { border-bottom: 1px solid var(--line-soft); padding-bottom: 10px; margin-bottom: 10px; }
.match-side .side-block:last-child { border-bottom: 0; margin-bottom: 0; padding-bottom: 0; }
.lineup-list { display: grid; gap: 4px; font-size: 10px; color: var(--muted); }
.lineup-list .ll-row { display: flex; align-items: center; gap: 6px; }
.lineup-list .ll-pos { width: 26px; color: var(--muted-2); font-weight: 800; font-size: 8px; }
.lineup-list .ll-name { color: #d9e4e0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.match-footer { position: sticky; bottom: 0; display: flex; justify-content: center; align-items: center; gap: 10px; flex-wrap: wrap; max-width: 1180px; margin: 12px auto 0; padding: 10px; background: rgba(6,10,12,0.8); border: 1px solid var(--line); border-radius: 14px; backdrop-filter: blur(10px); }
.speed-group { display: flex; gap: 4px; background: rgba(255,255,255,0.04); padding: 3px; border-radius: 9px; }
.speed-btn { border: 0; background: transparent; color: var(--muted); font-size: 11px; font-weight: 800; padding: 6px 9px; border-radius: 6px; }
.speed-btn.active { background: var(--green-dim); color: var(--green); }
.goal-flash {
  position: fixed; inset: 0; z-index: 130; display: grid; place-items: center; pointer-events: none;
  background: radial-gradient(circle, rgba(56,224,123,0.18), transparent 60%); animation: goalflash .9s ease both;
}
.goal-flash b { font-size: clamp(48px, 13vw, 150px); font-weight: 950; letter-spacing: -0.06em; color: var(--green); text-shadow: 0 10px 60px rgba(56,224,123,0.5); }
@keyframes goalflash { 0% { opacity: 0; transform: scale(.9); } 20% { opacity: 1; transform: scale(1); } 80% { opacity: 1; } 100% { opacity: 0; } }

/* ============================================================
   Toast
   ============================================================ */
#toast-root { position: fixed; right: 18px; bottom: calc(18px + var(--safe-bottom)); z-index: 200; display: grid; gap: 8px; width: min(360px, calc(100vw - 36px)); pointer-events: none; }
.toast {
  background: rgba(18, 29, 35, 0.96); border: 1px solid var(--line); border-left: 3px solid var(--green);
  border-radius: 11px; padding: 11px 13px; box-shadow: var(--shadow); font-size: 12px; line-height: 1.4;
  animation: toast-in .25s ease both; pointer-events: auto;
}
.toast.bad { border-left-color: var(--red); }
.toast.gold { border-left-color: var(--gold); }
.toast.out { animation: toast-out .25s ease both; }
@keyframes toast-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@keyframes toast-out { to { opacity: 0; transform: translateY(8px); } }

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 1180px) {
  .grid.two { grid-template-columns: 1fr; }
  .coach-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .match-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr); }
  .match-side { grid-column: 1 / -1; }
  .match-side .side-block { display: none; }
  .landing { grid-template-columns: 1fr; }
  .landing-hero { min-height: 46vh; border-right: 0; border-bottom: 1px solid var(--line); }
  .landing-panel { padding-top: 28px; }
}
@media (max-width: 980px) {
  .shell { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .mobile-nav {
    display: flex; position: fixed; left: 0; right: 0; bottom: 0; z-index: 50;
    background: rgba(8, 13, 16, 0.94); backdrop-filter: blur(16px); border-top: 1px solid var(--line);
    padding: 6px 6px calc(6px + var(--safe-bottom)); justify-content: space-around; gap: 2px;
  }
  .mobile-nav .mn-item {
    flex: 1; display: flex; flex-direction: column; align-items: center; gap: 2px; border: 0;
    background: transparent; color: var(--muted); font-size: 8px; font-weight: 700; padding: 5px 2px; border-radius: 8px;
  }
  .mobile-nav .mn-item svg { width: 19px; height: 19px; }
  .mobile-nav .mn-item.active { color: var(--green); background: rgba(56,224,123,0.08); }
  .view { padding-bottom: 95px; }
  .stats-grid, .squad-summary, .summary-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .fin-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .grid.three, .grid.four { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .filters { grid-template-columns: 1fr 1fr; }
  .filters .filter:first-child { grid-column: 1 / -1; }
  .match-grid { grid-template-columns: 1fr; }
  .match-feed { max-height: 220px; }
  .match-side { display: none; }
  .match-scoreline { grid-template-columns: 1fr auto 1fr; }
  .match-team { flex-direction: column; text-align: center; gap: 6px; }
  .match-team.away { flex-direction: column; text-align: center; }
  .match-team .crest { --size: 40px; }
  .match-score { font-size: 40px; }
}
@media (max-width: 720px) {
  .landing-hero { padding: 26px 20px; min-height: 42vh; }
  .hero-title { margin: 14px 0 16px; }
  .hero-features { grid-template-columns: 1fr; margin-top: 22px; }
  .landing-panel { padding: 22px 16px 40px; }
  .club-grid { grid-template-columns: 1fr; max-height: 290px; }
  .topbar { padding: 12px 14px; }
  .topbar-title { font-size: 15px; }
  .topbar-meta .budget-chip { display: none; }
  .topbar-meta .budget-chip:first-child { display: flex; }
  .user-pill .up-name { display: none; }
  .user-pill { padding-right: 6px; }
  .view { padding: 14px; padding-bottom: 95px; }
  .page-title { font-size: 26px; }
  .card { padding: 14px; border-radius: 15px; }
  .dash-hero { padding: 16px; border-radius: 18px; }
  .hero-club { gap: 10px; }
  .hero-club .crest { --size: 52px; }
  .hero-next { width: 100%; justify-content: stretch; }
  .next-card-mini { width: 100%; }
  .next-match { padding: 12px 10px; }
  .next-team .nt-name { font-size: 11px; }
  .grid.three, .grid.four, .grid.two-even, .coach-grid { grid-template-columns: 1fr; }
  .fin-grid { grid-template-columns: 1fr; }
  .detail-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .attr-grid { grid-template-columns: 1fr; }
  .form-row { grid-template-columns: 1fr; }
  .modal-body { padding: 14px; }
  .modal-head { padding: 14px; }
  .modal-foot { padding: 12px 14px calc(14px + var(--safe-bottom)); }
  .modal { max-height: 92vh; border-radius: 16px; }
  .match-overlay { padding: 10px 8px calc(8px + var(--safe-bottom)); }
  .match-scoreline { gap: 4px; }
  .match-team .mt-name { font-size: 12px; }
  .match-team .crest { --size: 32px; }
  .match-score { font-size: 32px; gap: 5px; }
  .match-clock { font-size: 11px; }
  .match-footer { gap: 6px; padding: 8px; }
  .match-footer .btn { padding: 8px 10px; font-size: 11px; min-height: 36px; }
  .pitch { aspect-ratio: 1.45; }
  .next-vs .vs-time { font-size: 16px; }
  .toast-root, #toast-root { right: 10px; left: 10px; width: auto; bottom: calc(74px + var(--safe-bottom)); }
  .squad-summary { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .stats-grid { gap: 7px; }
  .stat-value { font-size: 21px; }
  .table-toolbar { gap: 6px; }
  .table-toolbar .select { flex: 1; min-width: 130px; }
  .lineup-grid { grid-template-columns: 1fr; }
  .academy-banner .ab-actions { width: 100%; margin-left: 0; }
  .academy-banner .ab-actions .btn { flex: 1; }
  .league-tabs-lg { margin-bottom: 10px; }
  .league-tab-lg { padding: 8px 10px; font-size: 11px; }
  .fixture-row { padding: 8px; gap: 5px; }
  .fixture-team { font-size: 10px; gap: 5px; }
  .fixture-team .crest { --size: 20px; }
  .player-hero .ph-club { margin-left: 0; width: 100%; }
}
@media (max-width: 430px) {
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .budget-chip { min-width: 76px; }
  .budget-chip b { font-size: 12px; }
  .match-team .mt-sub { display: none; }
  .match-score { font-size: 27px; }
  .match-team .crest { --size: 27px; }
  .match-team .mt-name { font-size: 10px; }
  .match-comp { font-size: 8px; }
  .mobile-nav .mn-item { font-size: 7px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; scroll-behavior: auto !important; }
}

